do $$ begin
 if exists(select 1 from grid_new_players n join public.players p on p.id=n.id where not exists(select 1 from public.player_external_ids e where e.player_id=n.id and e.provider in ('api_football','api-football') and e.external_id=n.external_id::text)) or exists(select 1 from grid_new_players n join public.player_external_ids e on e.external_id=n.external_id::text and e.provider in ('api_football','api-football') where e.player_id<>n.id) then raise exception 'Grid ID allocation has changed. Re-export and regenerate; no data was changed.'; end if;
end $$;
insert into public.players(id,display_name) select id,display_name from grid_new_players on conflict(id) do nothing;
insert into public.player_external_ids(player_id,provider,external_id) select id,'api_football',external_id::text from grid_new_players on conflict(player_id,provider) do nothing;
select setval(pg_get_serial_sequence('public.players','id'),greatest((select max(id) from public.players),(select last_value from public.players_id_seq)),true);
insert into public.countries(name) select distinct nationality from grid_profile_import where nationality is not null on conflict(name) do nothing;
update public.players p set nationality_country_id=coalesce(p.nationality_country_id,c.id),full_name=coalesce(nullif(p.full_name,''),i.full_name),photo_url=coalesce(nullif(p.photo_url,''),i.photo),primary_position=coalesce(nullif(p.primary_position,''),i.position)
from grid_profile_import i join public.countries c on c.name=i.nationality where p.id=i.id and exists(select 1 from public.player_external_ids e where e.player_id=p.id and e.provider in ('api_football','api-football') and e.external_id=i.external_id::text);
insert into public.player_season_stats(player_id,club_id,competition_id,season_start_year,appearances,source_provider,season_status,last_synced_at)
select x.player_id,x.club_id,x.competition_id,x.season_start_year,x.appearances,'api_football',case when x.season_start_year=2026 then 'current' else 'completed' end,now()
